using MediatR;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TheMathAndScienceAcademy.Api.Authorization;using TheMathAndScienceAcademy.Application.Features.Subjects;
namespace TheMathAndScienceAcademy.Api.Controllers;
[ApiController,Authorize,Route("api/subjects")] public class SubjectsController:ControllerBase{readonly IMediator _m;public SubjectsController(IMediator m)=>_m=m;[HttpGet,HasPermission("subject.view")]public async Task<IActionResult> Get()=>Ok(await _m.Send(new GetSubjectsQuery()));[HttpGet("{id:guid}"),HasPermission("subject.view")]public async Task<IActionResult> Get(Guid id)=>Ok(await _m.Send(new GetSubjectQuery(id)));[HttpPost,HasPermission("subject.create")]public async Task<IActionResult> Create(CreateSubjectCommand c)=>Ok(await _m.Send(c));[HttpPut("{id:guid}"),HasPermission("subject.update")]public async Task<IActionResult> Update(Guid id,UpdateSubjectCommand c){c.Id=id;return Ok(await _m.Send(c));}[HttpDelete("{id:guid}"),HasPermission("subject.delete")]public async Task<IActionResult> Delete(Guid id)=>Ok(await _m.Send(new DeleteSubjectCommand(id)));}
